<template><div class="module-editor-fields"><h3>能力方法</h3><label>眉题<input v-model="value.eyebrow" /></label><label>区块标题<input v-model="value.title" /></label><label>说明<textarea v-model="value.subtitle" rows="2" /></label><div v-for="item in value.items || []" :key="item.number" class="editor-list-row"><strong>{{ item.number }}</strong><input v-model="item.title" /><input v-model="item.description" /></div></div></template>
